      let r = textureSampleLevel(inputTexture, inputSampler, uv + dir * rr * (1.0 + params.dispersion * 0.5), 0.0).r;
      let g = textureSampleLevel(inputTexture, inputSampler, uv + dir * rr, 0.0).g;
