      let src = (uv + dir * rr - vec2f(0.5)) * vec2f(aspect, 1.0);
      let onAxis = exp(-dot(src, src) / (2.0 * params.axis * params.axis));
      sum = sum + vec3f(r, g, b) * select(0.5, 1.0, j == 0) * onAxis;
