fn distort(uv: vec2f, k: f32, aspect: f32) -> vec2f {
  let c = (uv - vec2f(0.5)) * vec2f(aspect, 1.0);
  let r2 = dot(c, c);
  let f = 1.0 + k * r2;
  return c * f / vec2f(aspect, 1.0) / (1.0 + k * 0.25) + vec2f(0.5);
