  let c = (src - vec2f(0.5)) * vec2f(aspect, 1.0);
  let r2 = dot(c, c) / (0.25 * aspect * aspect + 0.25);
  let radial = normalize(c + vec2f(1e-5)) / vec2f(aspect, 1.0);
